INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(53611, 'Jeremiah 44:21', 'Jeremiah', 44, 21, '”ولې ستاسو هم دا خيال دے چې ګنې مالِک خُدائ ته دا پته نشته څۀ چې تاسو او ستاسو پلار نيکۀ، ستاسو بادشاهانو او سرکارى کسانو، او ټولو خلقو بُتانو ته د يهوداه په ښارونو او د يروشلم په کوڅو کښې خوشبوئى سوزولې ده؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_21.mp3', '', 1761754199, 1761754199),
(53612, 'Jeremiah 44:22', 'Jeremiah', 44, 22, 'دا ځکه وشُو چې، نور مالِک خُدائ ستاسو د شرارت نه ډک او حرام کارونه نۀ شو برداشت کولے، نو د دې په وجه ستاسو زمکه د لعنت مثال وګرځېده، او په صحرا او کنډرو بدله شوه چې تر ننه پورې هيڅ څوک په کښې نۀ اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_22.mp3', '', 1761754199, 1761754199),
(53613, 'Jeremiah 44:23', 'Jeremiah', 44, 23, 'دا مصيبتونه ځکه په تاسو باندې راغلل چې تاسو بُتانو ته خوشبو وسوزوله او د مالِک خُدائ خلاف مو ګناه وکړه. تاسو د هغۀ د حکمونو منلو نه اِنکار وکړو او نۀ مو د هغۀ په لارښودنو، اصُولو او شريعت باندې عمل وکړو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_23.mp3', '', 1761754199, 1761754199),
(53614, 'Jeremiah 44:24', 'Jeremiah', 44, 24, 'نو بيا يرمياه ټولو ناريناؤ او زناناؤ ته وفرمائيل چې، ”اے د يهوداه خلقو تاسو څوک چې په مِصر کښې اوسېږئ د مالِک خُدائ کلام ته غوږ ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_24.mp3', '', 1761754199, 1761754199),
(53615, 'Jeremiah 44:25', 'Jeremiah', 44, 25, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک داسې فرمائى چې، تاسو او ستاسو ښځو ووئيل چې، مونږ به ضرور خپلې وعدې پوره کوُو او آسمانې مَلِکې ته به د خوشبو سوزولو او د څښلو نذرانې پېش کوُو. نو تاسو چې څۀ کول نو هغه وکړئ او خپله وعده او منښته هغې ته پوره کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_25.mp3', '', 1761754199, 1761754199),
(53616, 'Jeremiah 44:26', 'Jeremiah', 44, 26, 'خو اوس تاسو ټول د مالِک خُدائ دې پېغام ته غوږ ونيسئ، تاسو د يهوداه ټولو خلقو څوک چې اوس په مِصر کښې اوسېږئ، زۀ په ژوندى مالِک قادر مطلق خُدائ قسم خورم، مالِک خُدائ فرمائى چې، زما نوم به نور هيڅکله په مِصر کښې د يو يهودى په خولۀ وانۀ خستلے شى. په تاسو کښې به يو هم زما نوم د دُعا او د قسم خوړلو دپاره استعمال نۀ کړى، هغه دا چې، په يقين سره مالِک قادر مطلق خُدائ ژوندے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_26.mp3', '', 1761754199, 1761754199),
(53617, 'Jeremiah 44:27', 'Jeremiah', 44, 27, 'زۀ به په تاسو ضرور افتونه نازل کړم، نه چې آبادى. د يهوداه هر يو کس څوک چې اوس په مِصر کښې اوسيږى ټول به جنګ او يا په قحط کښې مړۀ شى ترڅو چې يو هم ژوندے پاتې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_27.mp3', '', 1761754199, 1761754199),
(53618, 'Jeremiah 44:28', 'Jeremiah', 44, 28, 'صرف يو څو کسان به د مرګ نه وتښتى او د مِصر نه به يهوداه ته واپس شى. نو بيا ټول هغه کسان چې مِصر ته راغلى دى نو هغوئ ته به دا پته ولګى چې د چا خبره رښتيا ده، زما او کۀ د هغوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_28.mp3', '', 1761754199, 1761754199),
(53619, 'Jeremiah 44:29', 'Jeremiah', 44, 29, 'مالِک خُدائ فرمائى چې، دا به تاسو دپاره نښه وى چې زۀ په دې ځائ کښې تاسو ته سزا درکړم، نو تاسو به په دې پوهه شئ چې ما ستاسو خلاف صرف خبرې نۀ دى کړې بلکې ضرور به سزا هم درکوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_29.mp3', '', 1761754199, 1761754199),
(53620, 'Jeremiah 44:30', 'Jeremiah', 44, 30, 'مالِک خُدائ فرمائى چې، لکه څنګه چې ما د يهوداه بادشاه صدقياه د بابل بادشاه نبوکدنضر ته حواله کړو، دغه شان به زۀ د فِرعون حفرع د مِصر بادشاه هم د هغۀ دشمنانو ته حواله کړم څوک چې د دۀ مرګ پسې ګرځى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah44_verse_30.mp3', '', 1761754199, 1761754199),
(53621, 'Proverbs 25:1', 'Proverbs', 25, 1, 'دا هم د سلیمان هغه متلونه دي چې د یهودا د پاچا حزقیا کاتبانو راټول کړي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_1.mp3', '', 1761754199, 1761754199),
(53622, 'Proverbs 25:2', 'Proverbs', 25, 2, 'دا د خدای لویي ده چې رازونه پټ ساتي د یوې موضوع څېړل د پاچا لویي ښکاره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_2.mp3', '', 1761754199, 1761754199),
(53623, 'Proverbs 25:3', 'Proverbs', 25, 3, 'لکه څنګه چې اسمان لوړ او ځمکه ژوره ده همداسې د پاچاهانو د زړونو رازونه هم پټ دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_3.mp3', '', 1761754199, 1761754199),
(53624, 'Proverbs 25:4', 'Proverbs', 25, 4, 'د سپینو زرو نه ناپاکي لېرې کړه چې زرګر ترې ښایسته لوښی جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_4.mp3', '', 1761754199, 1761754199),
(53625, 'Proverbs 25:5', 'Proverbs', 25, 5, 'د پاچا له حضور نه بدکاران لېرې کړه چې تخت یې د عدالت په بنیاد ټینګ پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_5.mp3', '', 1761754199, 1761754199),
(53626, 'Proverbs 25:6', 'Proverbs', 25, 6, 'د پاچا په حضور کې ځان لوړ مه ګڼه او د لویو خلکو په ځای مه کښېنه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_6.mp3', '', 1761754199, 1761754199),
(53627, 'Proverbs 25:7', 'Proverbs', 25, 7, 'نو دا به ښه وي چې هغه تاته ووایي: «راشه او زما په خوا کې کښېنه» له دې نه چې د مشرانو په مخکې دې سپک کړي او په لاندې ځای کې دې کښېنوي. څه چې تا په خپلو سترګو لیدلي دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_7.mp3', '', 1761754199, 1761754199),
(53628, 'Proverbs 25:8', 'Proverbs', 25, 8, 'نو په محکمه کې په ویلو بیړه مه کوه هسې نه چې تا ملامته او بیا دې رسوا کړي. که داسې وشي نو په اخر کې به ته څه کوې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_8.mp3', '', 1761754199, 1761754199),
(53629, 'Proverbs 25:9', 'Proverbs', 25, 9, 'په یوه دعوه کې د هرچا سره مخامخ بحث کوه او د بل چا راز ورته مه ښکاره کوه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_9.mp3', '', 1761754199, 1761754199),
(53630, 'Proverbs 25:10', 'Proverbs', 25, 10, 'هسې نه چې څوک یې واوري او تا وشرموي او بدنامي به دې هېڅکله ختمه نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_10.mp3', '', 1761754199, 1761754199),
(53631, 'Proverbs 25:11', 'Proverbs', 25, 11, 'په ځای خبره داسې ده لکه د سپینو زرو په ګاڼه کې چې د سرو زرو مرۍ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_11.mp3', '', 1761754199, 1761754199),
(53632, 'Proverbs 25:12', 'Proverbs', 25, 12, 'د حکمت د خاوند نصیحت، اورېدونکي ته داسې دی لکه په غوږ کې د خالصو سرو زرو غوږوالۍ او یا ګاڼه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_12.mp3', '', 1761754199, 1761754199),
(53633, 'Proverbs 25:13', 'Proverbs', 25, 13, 'صادق استازی د خپل لېږونکي دپاره داسې دی لکه د لو په وخت کې چې د غرونو د واورې یخوالی وي چې د خپل بادار روح تازه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_13.mp3', '', 1761754199, 1761754199),
(53634, 'Proverbs 25:14', 'Proverbs', 25, 14, 'څوک چې د تحفې ورکولو لافې وهي او نه یې ورکوي لکه د هغې ورېځې او باد په شان دی چې باران نه وروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_14.mp3', '', 1761754199, 1761754199),
(53635, 'Proverbs 25:15', 'Proverbs', 25, 15, 'د صبر په وسیله یو حکمران هم رضا کیږي او نرمه ژبه هډوکي ټوټې ټوټې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_15.mp3', '', 1761754199, 1761754199),
(53636, 'Proverbs 25:16', 'Proverbs', 25, 16, 'که شات پیدا کړې نو د اړتیا نه ډېر مه خوره هسې نه چې زیات وخورې او زړه دې بد شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_16.mp3', '', 1761754199, 1761754199),
(53637, 'Proverbs 25:17', 'Proverbs', 25, 17, 'د خپل ګاونډي کور ته ډېر مه ورځه هسې نه چې زړه یې بد شي او ستا نه کرکه وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_17.mp3', '', 1761754199, 1761754199),
(53638, 'Proverbs 25:18', 'Proverbs', 25, 18, 'څوک چې د بل په خلاف د دروغو تور لګوي لکه د لور یا تورې او یا تېره غشي په څېر زیان رسوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_18.mp3', '', 1761754199, 1761754199),
(53639, 'Proverbs 25:19', 'Proverbs', 25, 19, 'د سختۍ په وخت کې په بې‌اعتباره سړي باور کول داسې دي لکه په خوځېدلي غاښ خوړل او یا په ګوډه پښه ګرځېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_19.mp3', '', 1761754199, 1761754199),
(53640, 'Proverbs 25:20', 'Proverbs', 25, 20, 'د مات زړه خاوند ته د خوشحالۍ سندرې ویل داسې دي لکه د یخنۍ په ورځ د چا نه څادر اخیستل او یا یې په زخمونو باندې مالګه شیندل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_20.mp3', '', 1761754199, 1761754199),
(53641, 'Proverbs 25:21', 'Proverbs', 25, 21, 'که ستا دښمن وږی وي نو هغه ته خواړه ورکړه چې ویې خوري او که چېرې تږی وي نو هغه ته اوبه ورکړه چې ویې څښي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_21.mp3', '', 1761754199, 1761754199),
(53642, 'Proverbs 25:22', 'Proverbs', 25, 22, 'په دې کار به ته د هغه په سر باندې اور بل کړې او څښتن به تاته اجر درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_22.mp3', '', 1761754199, 1761754199),
(53643, 'Proverbs 25:23', 'Proverbs', 25, 23, 'لکه څنګه چې د شمال باد باران راولي همداسې غیبت د سړي په مخکې غوسه پیدا کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_23.mp3', '', 1761754199, 1761754199),
(53644, 'Proverbs 25:24', 'Proverbs', 25, 24, 'د کوټې د سر دپاسه په یو کنج کې اوسېدل د جګړه‌مارې ښځې سره په کور کې د اوسېدلو نه ښه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_24.mp3', '', 1761754199, 1761754199),
(53645, 'Proverbs 25:25', 'Proverbs', 25, 25, 'د لېرې ځای نه د خوشحالۍ زېري اورېدل داسې دي لکه تږي سړي ته یخې اوبه ورکول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_25.mp3', '', 1761754199, 1761754199),
(53646, 'Proverbs 25:26', 'Proverbs', 25, 26, 'د یو نېک انسان بدکارانو ته تسلیمېدل لکه د خټو نه ډکه چینه او د څاه چټلېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_26.mp3', '', 1761754199, 1761754199),
(53647, 'Proverbs 25:27', 'Proverbs', 25, 27, 'لکه څنګه چې د ډېرو شاتو خوړل ښه کار نه دی همداسې د ځان دپاره عزت او درناوی غوښتل ښه کار نه دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_27.mp3', '', 1761754199, 1761754199),
(53648, 'Proverbs 25:28', 'Proverbs', 25, 28, 'څوک چې د خپل نفس مخنیوی نه شي کولای داسې دی لکه یو ښار چې دېوالونه یې سوري او وران شوي وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs25_verse_28.mp3', '', 1761754199, 1761754199),
(53649, 'Jeremiah 5:1', 'Jeremiah', 5, 1, 'د يروشلم په کوڅو کښې ښکته پورته منډې ووهئ. اخوا ديخوا په غور سره وګورئ او په چوکونو کښې لټون وکړئ. کۀ چرې تاسو داسې يو کس هم پېدا کړئ چې هغه صداقت او اِنصاف کوى او په رښتياو پسې ګرځى، نو زۀ به دا ښار نۀ تباه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_1.mp3', '', 1761754199, 1761754199),
(53650, 'Jeremiah 5:2', 'Jeremiah', 5, 2, 'کۀ څۀ هم چې دوئ زما په نوم قسم خورى چې، ”مالِک خُدائ ژوندے دے،“ خو بيا هم دوئ دروغ وائى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_2.mp3', '', 1761754199, 1761754199),
(53651, 'Jeremiah 5:3', 'Jeremiah', 5, 3, 'اے مالِکه خُدايه ستا سترګې صداقت ليدل غواړى. کۀ څۀ هم چې تا دوئ ووهل خو دوئ ته پرې څۀ خفګان ونۀ رسېدو، تا هغوئ ته سزا ورکړه خو بيا هم دوئ اصلاح نۀ شُو. او دوئ خپل زړونه د کاڼى نه هم سخت کړل او د توبې ويستلو نه يې اِنکار وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_3.mp3', '', 1761754199, 1761754199),
(53652, 'Jeremiah 5:4', 'Jeremiah', 5, 4, 'نو بيا ما سوچ وکړو چې، ”دا خو غريبانان او جاهله مخلوق دے، دوئ ځکه بې‌وقوفه کارونه کوى چې د مالِک خُدائ لار نۀ پېژنى او د هغۀ د حکمونو نه ناواقفه دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_4.mp3', '', 1761754199, 1761754199),
(53653, 'Jeremiah 5:5', 'Jeremiah', 5, 5, 'نو زۀ به د دوئ مشرانو له لاړ شم او هغوئ سره به خبرې وکړم. نو دوئ به ضرور د مالِک خُدائ د لارو او حکمونو نه خبر وى.“ خو افسوس چې دې مشرانو هم د مالِک خُدائ د تابعدارۍ زنځير او جغ مات کړو او د خپلو ځانونو نه يې اخوا کړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_5.mp3', '', 1761754199, 1761754199),
(53654, 'Jeremiah 5:6', 'Jeremiah', 5, 6, 'نو په دې وجه به د ځنګل نه زمرے راشى او دوئ به وخورى، او د دشتو نه به ليوۀ راشى او دوئ به برباد کړى، او پړانګ به ورته پټ کښېنى ترڅو چې څوک هم د ښار نه رابهر شى نو هغه به ټوټې ټوټې کړى. ځکه چې هغوئ غټ سرکشه دى او په څو ځله مرتد شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_6.mp3', '', 1761754199, 1761754199),
(53655, 'Jeremiah 5:7', 'Jeremiah', 5, 7, 'مالِک خُدائ وفرمائيل، ”زۀ څنګه تاسو معاف کړم؟ ستاسو بچو زۀ پرېښے يم او دوئ په هغه معبودانو يقين وکړو چې په حقيقت کښې هغه رښتينى نۀ دى. کۀ څۀ هم ما د هغوئ ټول ضرورتونه پوره کړل، خو هغوئ لکه د بې‌وفا ښځې په شان زنا وکړه او د چکلې مخې ته يې قطارونه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_7.mp3', '', 1761754199, 1761754199),
(53656, 'Jeremiah 5:8', 'Jeremiah', 5, 8, 'دوئ لکه د ښۀ څربه مستو آسونو په شان دى چې هر يو د خپل ګاونډى د ښځې پسې هڼيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_8.mp3', '', 1761754199, 1761754199),
(53657, 'Jeremiah 5:9', 'Jeremiah', 5, 9, 'مالِک خُدائ فرمائى، ”ولې زۀ دوئ ته د دې بې‌شرمه کارونو په وجه سزا ورنۀ کړم څۀ؟ او ولې د داسې قوم نه بدله وانۀ خلم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_9.mp3', '', 1761754199, 1761754199),
(53658, 'Jeremiah 5:10', 'Jeremiah', 5, 10, 'لاړ شئ او د هغوئ د انګورو باغونه تالا والا کړئ خو بلکل په پوره توګه يې مۀ تباه کوئ. او د انګور بوټى څانګې راماتې کړئ، ځکه چې دا خلق زما نۀ دى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_10.mp3', '', 1761754199, 1761754199),
(53659, 'Jeremiah 5:11', 'Jeremiah', 5, 11, 'مالِک خُدائ دا فرمائى، ”د اِسرائيل او يهوداه خلقو ما سره هر قسمه بې‌وفائى او خيانت کړے دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_11.mp3', '', 1761754199, 1761754199),
(53660, 'Jeremiah 5:12', 'Jeremiah', 5, 12, 'دوئ د مالِک خُدائ په حقله دروغ ووئيل او وائى، ”هغه به مونږ سره هيڅ هم نۀ کوى. په مونږ به مصيبت نۀ راځى. قحط او جنګ به هم په مونږ باندې نۀ راځى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_12.mp3', '', 1761754199, 1761754199),
(53661, 'Jeremiah 5:13', 'Jeremiah', 5, 13, 'دوئ وائى، ”پېغمبران هسې فضول خبرې کوى او دوئ سره د خُدائ پاک له طرف نه پېغام نشته. د کوم مصيبت نه چې مونږ يروى هغه دې په دوئ باندې په خپله راشى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_13.mp3', '', 1761754199, 1761754199),
(53662, 'Jeremiah 5:14', 'Jeremiah', 5, 14, 'نو ځکه مالِک خُدائ ربُ الافواج خُدائ فرمائى، ”اے يرمياه، نو لکه څنګه چې دوئ داسې خبرې کوى نو زۀ هم خپل کلام ستا په خولۀ کښې لکه د اور په شان اچوم او دوئ نه خشاک جوړوم چې دوئ وسوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_14.mp3', '', 1761754199, 1761754199),
(53663, 'Jeremiah 5:15', 'Jeremiah', 5, 15, 'مالِک خُدائ فرمائى، اے اِسرائيله، زۀ به د لرې ځائ نه ستا خلاف يو زورَور او پخوانے قوم راولېږم چې په تا حمله وکړى چې تۀ يې په ژبه او خبرو باندې نۀ پوهېږې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_15.mp3', '', 1761754199, 1761754199),
(53664, 'Jeremiah 5:16', 'Jeremiah', 5, 16, 'د هغوئ سره وژونکى غشى دى او ټول تکړه او زورَور فوجيان دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_16.mp3', '', 1761754199, 1761754199),
(53665, 'Jeremiah 5:17', 'Jeremiah', 5, 17, 'هغوئ به ستاسو فصلونه او خوراک لواړ تېر کړى، هغوئ به ستاسو زامن او لوڼه ووژنى. هغوئ به ستاسو رَمې او څاروى تباه کړى، او هغوئ به ستاسو د انګورو او د اينځر ونې تباه کړى. تاسو چې په کومو محفوظو ښارونو باندې بهروسه کوئ نو د هغې لښکرې به يې تباه برباد کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_17.mp3', '', 1761754199, 1761754199),
(53666, 'Jeremiah 5:18', 'Jeremiah', 5, 18, 'مالِک خُدائ فرمائى چې، خو بيا هم په هغه ورځو کښې به زۀ تاسو په مکمل توګه نۀ تباه کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_18.mp3', '', 1761754199, 1761754199),
(53667, 'Jeremiah 5:19', 'Jeremiah', 5, 19, 'اے يرمياه کۀ چرې خلق تا نه تپوس وکړى چې دا هر څۀ زمونږ مالِک خُدائ پاک ولې مونږ سره وکړل؟ نو تۀ دوئ ته ووايه، چې تاسو خپل حقيقى خُدائ پرېښودو او د هغۀ په ځائ مو په خپل مُلک کښې د غېرو معبودانو خِدمت وکړو، نو په دې وجه به تاسو په پردى وطن کښې د پردو خلقو خِدمت وکړئ.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_19.mp3', '', 1761754199, 1761754199),
(53668, 'Jeremiah 5:20', 'Jeremiah', 5, 20, 'مالِک خُدائ وفرمائيل چې، ”د يعقوب اولاد ته اعلان وکړه، د يهوداه خلقو ته ووايه،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_20.mp3', '', 1761754199, 1761754199),
(53669, 'Jeremiah 5:21', 'Jeremiah', 5, 21, 'اے کم عقلو او بې‌شعوره خلقو، تاسو سترګې لرئ خو وينئ نه او غوږونه لرئ خو اورئ نه، ما ته غوږ ونيسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_21.mp3', '', 1761754199, 1761754199),
(53670, 'Jeremiah 5:22', 'Jeremiah', 5, 22, 'مالِک خُدائ فرمائى، تاسو به زما نه نۀ يرېږئ څۀ؟ تاسو به زما په حضور کښې د يرې نه نۀ ريږدېږئ څۀ؟ ما د سمندر دپاره د شګو حد مقرر کړے دے، دا مې ورته ابدى او پوخ حد مقرر کړے دے. کله چې سمندر په زور او مستۍ کښې هم راشى او د هغې چپې ډېر شور او زور هم وکړى خو بيا هم د مقرر شوى حد نه نۀ شى اوړېدلے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_22.mp3', '', 1761754199, 1761754199),
(53671, 'Jeremiah 5:23', 'Jeremiah', 5, 23, 'خو زما قوم سرکشه او د ضدناکو زړونو لرونکى دى. دوئ زما نه واوړېدل او زۀ يې پرېښودلم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_23.mp3', '', 1761754199, 1761754199),
(53672, 'Jeremiah 5:24', 'Jeremiah', 5, 24, 'دوئ هيڅکله خپل ځان سره دا نۀ دى وئيلى چې، راځئ د مالِک خُدائ نه يره وکړُو، څوک چې په مونږ باندې د منى او سپرلى موسم کښې بارانونه راوروى، او هغه مونږ ته د رېبلو موسم په مقرره وخت کښې راولى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_24.mp3', '', 1761754199, 1761754199),
(53673, 'Jeremiah 5:25', 'Jeremiah', 5, 25, 'ستاسو غلطيانو تاسو د دې عجيبه برکتونو نه محرومه کړئ. ستاسو ګناهونو تاسو د دې ښۀ څيزونو نه منع کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_25.mp3', '', 1761754199, 1761754199),
(53674, 'Jeremiah 5:26', 'Jeremiah', 5, 26, 'زما د غوره شوى قوم په مينځ کښې شريران پېدا کيږى. هغوئ لکه د مارغانو د ښکاريانو په شان په انتظار کښې ناست دى، دوئ د خلقو دپاره دام خوروى ترڅو هغوئ په کښې راګېر کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_26.mp3', '', 1761754199, 1761754199),
(53675, 'Jeremiah 5:27', 'Jeremiah', 5, 27, 'لکه څنګه چې د يو ښکارى پنجره د مارغانو نه ډکه وى، نو هم دغه شان د دوئ کور هم د شرارت او فساد نه ډک وى. هم دا وجه ده چې دوئ ډېر زورَور او مالداره شوى دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_27.mp3', '', 1761754199, 1761754199),
(53676, 'Jeremiah 5:28', 'Jeremiah', 5, 28, 'ښۀ خورى او څربه کيږى او د هغوئ د بدو کارونو څۀ حد نشته دے. او نۀ هغوئ د يتيمانانو سره مدد کوى چې ورته هغه څۀ مِلاو شى کوم يې چې حق دے، او نۀ د غريبانانو مدد کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_28.mp3', '', 1761754199, 1761754199),
(53677, 'Jeremiah 5:29', 'Jeremiah', 5, 29, 'نو مالِک خُدائ فرمائى چې، آيا زۀ دوئ ته په دې بدو کارونو کولو سره سزا ورنۀ کړم څۀ؟ او د داسې قوم نه بدله وانۀ خلم څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_29.mp3', '', 1761754199, 1761754199),
(53678, 'Jeremiah 5:30', 'Jeremiah', 5, 30, 'کوم کارونه چې په دې مُلک کښې وشو هغه خراب او قابل نفرت دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_30.mp3', '', 1761754199, 1761754199),
(53679, 'Jeremiah 5:31', 'Jeremiah', 5, 31, 'پېغمبران د دروغو پېغامونه ورکوى، او اِمامان هم د خپلې مرضۍ حکومت کوى. او زما غوره شوے قوم هم دا سلوک خوښوى. نو تۀ ما ته دا ووايه چې هرکله دا هر څۀ ختم شى نو تاسو به څۀ کوئ؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah5_verse_31.mp3', '', 1761754199, 1761754199),
(53680, 'Psalms 11:1', 'Psalms', 11, 1, 'زه په څښتن لرم باور، هغه به وساتي ما څنګه تاسو ماته دا ویلی شئ: «والوزه مرغۍ په شانتې غرونو ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_1.mp3', '', 1761754199, 1761754199),
(53681, 'Psalms 11:2', 'Psalms', 11, 2, 'بدکارانو تیار کړي دي خپل غشي هم راکش کړې یې لیندې خپلې دي چې د تیارې نه پرې نېکان وولي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_2.mp3', '', 1761754199, 1761754199),
(53682, 'Psalms 11:3', 'Psalms', 11, 3, 'که ویجاړ شي بنیادونه څه به وکړي بیا نېکان؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_3.mp3', '', 1761754199, 1761754199),
(53683, 'Psalms 11:4', 'Psalms', 11, 4, 'څښتن په خپل سپېڅلي کور کې دی د هغه تخت پاس په اسمان کې دی هغه ټول خلک څاري په هرځای کې او پوهیږي چې دوی څه کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_4.mp3', '', 1761754199, 1761754199),
(53684, 'Psalms 11:5', 'Psalms', 11, 5, 'اخلي امتحان د بدکارانو او نېکانو نه کوي نفرت د هغه چا چې زورزیاتی خوښوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_5.mp3', '', 1761754199, 1761754199),
(53685, 'Psalms 11:6', 'Psalms', 11, 6, 'وروي به سرې سکروټې او ګوګړ په بدکارانو وي په برخه به یې بادونه سوځوونکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_6.mp3', '', 1761754199, 1761754199),
(53686, 'Psalms 11:7', 'Psalms', 11, 7, 'څښتن نېک دی خوښوي نېک عملونه د څښتن دیدن به وکړي چې کوي نېک کردارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms11_verse_7.mp3', '', 1761754199, 1761754199),
(53687, 'Exodus 18:1', 'Exodus', 18, 1, 'یترون د مدیان کاهن او د موسی خسر واورېدل چې خدای د موسی او د اسراییلو د خلکو دپاره کوم کارونه کړي وو او څنګه یې هغوی له مصر څخه راوویستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_1.mp3', '', 1761754199, 1761754199),
(53688, 'Exodus 18:2', 'Exodus', 18, 2, 'څه موده مخکې موسی خپله ښځه صفوره او خپل دوه زامن لېږلي وو چې د هغه د خسر یترون سره واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_2.mp3', '', 1761754199, 1761754199),
(53689, 'Exodus 18:3', 'Exodus', 18, 3, 'د موسی د لومړني زوی نوم جرشون ؤ، ځکه کله چې هغه هلک پیدا شو، نو موسی ویلي وو: «زه په پردۍ خاوره کې مسافر یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_3.mp3', '', 1761754199, 1761754199),
(53690, 'Exodus 18:4', 'Exodus', 18, 4, 'هغه وویل: «زما د پلار خدای زما سره مرسته وکړه او زه یې له دې څخه وژغورلم چې فرعون مې ووژني» نو په دې خاطر یې د بل زوی نوم الیعازر کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_4.mp3', '', 1761754199, 1761754199),
(53691, 'Exodus 18:5', 'Exodus', 18, 5, 'یترون د موسی د ښځې او د هغې د دوو زامنو سره هغې دښتې ته راغی چېرته چې موسی سپېڅلي غره ته نژدې خېمه ودرولې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_5.mp3', '', 1761754199, 1761754199),
(53692, 'Exodus 18:6', 'Exodus', 18, 6, 'یترون هغه ته دا خبر ورولېږه: «زه ستا خسر یترون ستا د ښځې او دوو زامنو سره تاته درځم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_6.mp3', '', 1761754199, 1761754199),
(53693, 'Exodus 18:7', 'Exodus', 18, 7, 'نو موسی د هغه مخې ته ورغی او هغه ته یې د درناوي دپاره سر ټیټ کړ او هغه یې ښکل کړ. هغوی د یو بل د صحت پوښتنه وکړه او بیا د موسی خېمې ته ورننوتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_7.mp3', '', 1761754199, 1761754199),
(53694, 'Exodus 18:8', 'Exodus', 18, 8, 'موسی خپل خسر ته هغه کارونه بیان کړل چې څښتن د اسراییلو د خلاصون په خاطر په فرعون او د مصر په خلکو باندې کړي وو. همدارنګه د هغو ټولو سختیو په هکله یې ورته وویل چې هغوی په لاره کې ورسره مخامخ شوي وو او څښتن هغوی څنګه وژغورل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_8.mp3', '', 1761754199, 1761754199),
(53695, 'Exodus 18:9', 'Exodus', 18, 9, 'یترون د هغه احسان په سبب چې څښتن په اسراییلو باندې کړی ؤ چې هغوی یې له مصریانو څخه وژغورل، خوشحاله شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_9.mp3', '', 1761754199, 1761754199),
(53696, 'Exodus 18:10', 'Exodus', 18, 10, 'هغه وویل: «د څښتن ثنا او صفت دې وي چې تاسو یې د فرعون او د مصریانو څخه وژغورلئ! د څښتن ثنا او صفت دې وي چې خپل قوم یې له غلامۍ څخه وژغوره!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_10.mp3', '', 1761754199, 1761754199),
(53697, 'Exodus 18:11', 'Exodus', 18, 11, 'اوس زه پوهېږم چې څښتن له نورو ټولو خدایانو څخه لوی دی، ځکه چې هغه اسراییلیان د خپلو مغرورو دښمنانو څخه خلاص کړل.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_11.mp3', '', 1761754199, 1761754199),
(53698, 'Exodus 18:12', 'Exodus', 18, 12, 'بیا د موسی خسر یترون سوځېدونکې نذرانه او نورې قربانۍ خدای ته راوړلې او هارون د اسراییلو د ټولو مشرانو سره راغی چې د عبادت په ځای کې د موسی د خسر سره ډوډۍ وخوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_12.mp3', '', 1761754199, 1761754199),
(53699, 'Exodus 18:13', 'Exodus', 18, 13, 'بله ورځ موسی په یو ځای کې کښېناست چې د خلکو د دعوې په هکله پرېکړه وکړي او هغه د سهار څخه تر ماښام پورې بوخت ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_13.mp3', '', 1761754199, 1761754199),
(53700, 'Exodus 18:14', 'Exodus', 18, 14, 'کله چې یترون هغه ټول کارونه ولیدل چې موسی کول، هغه پوښتنه وکړه: «دا څه دي چې ته یې د خلکو دپاره کوې؟ دا کار ولې په یوازې ځان کوې او خلک د سهار څخه نیولې تر ماښامه پورې درڅخه چاپېر وي، چې ستا سره مشوره وکړي؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_14.mp3', '', 1761754199, 1761754199),
(53701, 'Exodus 18:15', 'Exodus', 18, 15, 'موسی په ځواب کې وویل: «ځکه چې خلک دلته راځي چې په دې پوه شي چې خدای د هغوی څخه څه غواړي چې ویې کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_15.mp3', '', 1761754199, 1761754199),
(53702, 'Exodus 18:16', 'Exodus', 18, 16, 'کله چې دوه تنه په خپل منځ کې کومه شخړه ولري، هغوی ماته راځي او زه دا پرېکړه کوم چې څوک په حقه دی. بیا هغوی ته د خدای فرمانونه او قوانین بیانوم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_16.mp3', '', 1761754199, 1761754199),
(53703, 'Exodus 18:17', 'Exodus', 18, 17, 'بیا یترون وویل: «ته دا کار په سمې طریقې سره نه کوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_17.mp3', '', 1761754199, 1761754199),
(53704, 'Exodus 18:18', 'Exodus', 18, 18, 'ته به خپل ځان او دا خلک سخت ستړي کړې. دا کار ستا دپاره ډېر سخت دی، ته یوازې دا کار نه شې کولای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_18.mp3', '', 1761754199, 1761754199),
(53705, 'Exodus 18:19', 'Exodus', 18, 19, 'اوس ماته غوږ ونیسه چې تاته یوه ښه مشوره درکړم او خدای به ستا سره مل وي. ستا دپاره دا ښه ده چې ته د خدای په حضور کې د قوم استازیتوب وکړې او د هغوی شخړې هغه ته راوړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_19.mp3', '', 1761754199, 1761754199),
(53706, 'Exodus 18:20', 'Exodus', 18, 20, 'هغوی ته د خدای فرمانونه او قوانین ورزده کړه او د ژوند کولو طریقه وروښایه او ورته وښایه چې څه باید وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_20.mp3', '', 1761754199, 1761754199),
(53707, 'Exodus 18:21', 'Exodus', 18, 21, 'خو د ټول قوم څخه لایق کسان وټاکه، داسې کسان چې د خدای څخه وېریږي او د اعتبار وړ وي او د رشوت څخه کرکه کوي. هغوی په زر کسیزه، سل کسیزه، پنځوس کسیزه او لس کسیزه ډلو باندې مشران وټاکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_21.mp3', '', 1761754199, 1761754199),
(53708, 'Exodus 18:22', 'Exodus', 18, 22, 'هغوی پرېږده چې په تلپاتې توګه د قاضیانو په توګه د قوم خدمت وکړي. هغوی به سختې دعوې تاته راوړي او د کوچنیو شخړو پرېکړه به په خپله کوي. په دې به ستا کار اسانه او بار به دې سپک شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_22.mp3', '', 1761754199, 1761754199),
(53709, 'Exodus 18:23', 'Exodus', 18, 23, 'که چېرې ته دا کار د خدای د حکم سره سم وکړې، هم به خپله ستړی نه شې او هم به د خلکو شخړې زر حل شي او په خاطر جمعۍ سره به وکولای شي چې خپلو کورونو ته لاړ شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_23.mp3', '', 1761754199, 1761754199),
(53710, 'Exodus 18:24', 'Exodus', 18, 24, 'موسی د خپل خسر مشوره ومنله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus18_verse_24.mp3', '', 1761754199, 1761754199);